class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        # Create a dummy node to build the result list
        dummy = ListNode(0)
        current = dummy

        # Initialize the heap
        heap = []
        for head in lists:
            if head is not None:
                heapq.heappush(heap, (head.val, head))

        # Process the heap to build the merged list
        while heap:
            val, node = heapq.heappop(heap)
            current.next = node
            current = current.next
            node = node.next
            if node is not None:
                heapq.heappush(heap, (node.val, node))

        return dummy.next

