from typing import Optional

class Node:
    def __init__(self, val: int = 0, neighbors: List['Node'] = None):
        self.val = val
        self.neighbors = neighbors if neighbors is not None else []

class Solution:
    def cloneGraph(self, node: Optional['Node']) -> Optional['Node']:
        if not node:
            return None

        visited = {}
        queue = deque([node])

        # Create the clone of the starting node
        clone = Node(node.val, [])
        visited[node] = clone

        while queue:
            current = queue.popleft()

            for neighbor in current.neighbors:
                if neighbor not in visited:
                    # Create a clone for the neighbor and add to visited
                    neighbor_clone = Node(neighbor.val, [])
                    visited[neighbor] = neighbor_clone
                    queue.append(neighbor)
                # Add the neighbor's clone to the current clone's neighbors
                visited[current].neighbors.append(visited[neighbor])

        return clone

