class Solution:
    def snakesAndLadders(self, board: List[List[int]]) -> int:
        n = len(board)
        target = n * n

        def get_pos(k: int) -> tuple:
            if k < 1 or k > target:
                return None
            r = (n - 1) - ((k - 1) // n)
            pos_in_row = (k - 1) % n
            if (n - 1 - r) % 2 == 0:
                c = pos_in_row
            else:
                c = (n - 1) - pos_in_row
            return (r, c)

        visited = set()
        queue = deque()
        queue.append((1, 0))
        visited.add(1)

        while queue:
            current, steps = queue.popleft()
            if current == target:
                return steps
            for i in range(1, 7):
                next_label = current + i
                if next_label > target:
                    continue
                pos = get_pos(next_label)
                if pos is None:
                    continue
                r, c = pos
                if board[r][c] != -1:
                    dest = board[r][c]
                else:
                    dest = next_label
                if dest == target:
                    return steps + 1
                if dest not in visited:
                    visited.add(dest)
                    queue.append((dest, steps + 1))
        return -1

