            nonlocal cameras
            if node is None:
                return False  # No camera placed here
            left = helper(node.left)
            right = helper(node.right)
            if not left and not right:
                # Neither child has a camera, place one here
                cameras += 1
                return True
            else:
                # At least one child has a camera, no need to place here
                return False

        # Check if the root is covered by any child
        if not helper(root):
            cameras += 1

        return cameras

