import re
from typing import Optional

class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

class Solution:
    def recoverFromPreorder(self, traversal: str) -> Optional[TreeNode]:
        if not traversal:
            return None

        # Parse the traversal string into a list of (depth, value)
        matches = re.findall(r'(-*)(\d+)', traversal)
        parsed = []
        for m in matches:
            depth = len(m[0])
            value = int(m[1])
            parsed.append((depth, value))

        # Create nodes
        nodes = [TreeNode(val) for (d, val) in parsed]
        if not nodes:
            return None

        root = nodes[0]

        for i in range(1, len(nodes)):
            current_node = nodes[i]
            current_depth = parsed[i][0]
            parent_depth = current_depth - 1

            # Find the parent: last node before i with depth parent_depth
            parent = None
            for j in range(i-1, -1, -1):
                if parsed[j][0] == parent_depth:
                    parent = nodes[j]
                    break

            if parent.left is None:
                parent.left = current_node
            else:
                parent.right = current_node

        return root

