class Solution:
    def count_segments(self, n: int, x: int, arr: List[int]) -> List[int]:
        x_indices = [i for i, num in enumerate(arr) if num == x]
        if not x_indices:
            return [n]
        result = [x_indices[0]]
        for i in range(1, len(x_indices)):
            prev = x_indices[i-1]
            current = x_indices[i]
            result.append(current - prev - 1)
        result.append(len(arr) - x_indices[-1] - 1)
        return result
